"""Radiology signs (tier 0.5k).

Edit freely — see data/__init__.py for how files are loaded."""


_RADIOLOGY = {
    'ground glass opacity': 'Ground Glass Opacity (GGO) — hazy ↑lung density on HRCT; vessels still visible through it; represents partial alveolar filling or interstitial thickening; causes: pneumonia (viral/bacterial/PCP), pulmonary edema, DAD (ARDS), IPF (with reticulation), adenocarcinoma in situ; COVID-19: bilateral peripheral GGO classic presentation; GGO with crazy-paving → alveolar proteinosis or organizing pneumonia',
    'crazy paving pattern': 'Crazy Paving Pattern — GGO + superimposed interlobular septal thickening on HRCT; resembles irregular paving stones; causes: pulmonary alveolar proteinosis (classic), COVID-19 pneumonia, ARDS, lipoid pneumonia, mucinous adenocarcinoma, hemorrhage; named for resemblance to irregular stone-paved roads',
    'tree-in-bud pattern': 'Tree-in-Bud Pattern — centrilobular nodules connected by branching lines on HRCT; represents filling of terminal bronchioles and alveolar ducts; causes: endobronchial spread of infection (TB — classic, MAC, bacterial bronchopneumonia), bronchiolitis, cystic fibrosis, diffuse panbronchiolitis; in TB: indicates active disease with endobronchial spread',
    'air bronchogram': 'Air Bronchogram Sign — air-filled bronchi visible within opacified (consolidated) lung parenchyma; indicates airspace disease with patent airways; causes: pneumonia (lobar consolidation), ARDS, pulmonary edema, lung cancer (adenocarcinoma), lymphoma; ABSENT in: pleural effusion, atelectasis from mucus plug (no air in bronchi), pleural-based lesions',
    'kerley b lines': 'Kerley B Lines — horizontal 1-2 cm lines perpendicular to pleural surface at lung bases on CXR; represent thickened interlobular septa; causes: pulmonary edema (MCC — elevated PCWP), lymphangitis carcinomatosa, viral pneumonia, pneumoconiosis; Kerley A lines = longer diagonal lines at upper zones; both indicate interstitial edema',
    'bat wing pattern': 'Bat-Wing / Butterfly Pattern — bilateral perihilar alveolar opacities sparing periphery on CXR; appearance resembles butterfly wings; classic for pulmonary edema (cardiogenic); also: alveolar proteinosis, ARDS (though typically more diffuse); perihilar distribution due to lymphatic drainage pattern',
    'hampton hump': "Hampton's Hump — wedge-shaped peripheral lung consolidation with base abutting pleural surface and dome pointing toward hilum; represents pulmonary infarction from PE; seen in ~30% of PE with infarction; often has ipsilateral pleural effusion; named for Aubrey Hampton",
    'westermark sign': "Westermark Sign — focal oligemia (decreased pulmonary vascularity) distal to a pulmonary embolus on CXR; represents regional hypoperfusion; low sensitivity (~15%) but specific for PE; area of ↓vascular markings with sharp cutoff; often seen with Hampton's hump ipsilaterally",
    'fleischner sign': 'Fleischner Sign — prominent enlarged pulmonary artery from acute massive PE; represents dilation of main or right pulmonary artery due to sudden ↑afterload; can also see enlarged right heart; low sensitivity; part of classic PE CXR findings (with Westermark + Hampton)',
    'signet ring sign': 'Signet Ring Sign — bronchus appears larger than accompanying pulmonary artery branch on CT; indicates bronchiectasis (bronchial dilation); normally airway diameter = adjacent artery; bronchoarterial ratio >1.5 = bronchiectasis; causes: CF, primary ciliary dyskinesia, post-infectious, ABPA, chronic aspiration; named for resemblance to signet ring (bronchus = stone, artery = band)',
    'air crescent sign': 'Air Crescent Sign — crescent of air between fungal mass (aspergilloma) and wall of pre-existing cavity on CT; pathognomonic for aspergilloma (Aspergillus colonizing lung cavity); also seen in the recovery phase of angioinvasive aspergillosis (as neutrophils return); found in patients with prior TB cavities, sarcoidosis, bullae',
    'halo sign': "Halo Sign — nodule surrounded by GGO halo on CT; in neutropenic/immunocompromised patients: angioinvasive aspergillosis (most important — nodule = fungal infarct, halo = hemorrhage); also: other fungal infections, TB, metastases (hemorrhagic), Wegener's/GPA, BAC/adenocarcinoma in situ; early sign — appears first, disappears before air crescent",
    'reverse halo sign': 'Reverse Halo (Atoll) Sign — central GGO surrounded by ring of consolidation on HRCT; classic for cryptogenic organizing pneumonia (COP); also: pulmonary infarction, invasive fungal infections, sarcoidosis, Pneumocystis jirovecii pneumonia, COVID-19',
    's1q3t3': 'S1Q3T3 Pattern — ECG finding in PE; prominent S in I, Q in III, T inversion in III; represents acute right heart strain; low sensitivity (~20%) but specific when present with other PE signs; sinus tachycardia is the MCC ECG finding in PE; also: new RBBB, right axis deviation, T inversions V1-V4',
    'double bubble sign': 'Double Bubble Sign — two gas-filled bubbles (stomach + dilated duodenum) on abdominal XR or prenatal US; classic for duodenal atresia; associated with Down syndrome (30%); annular pancreas; dx prenatal: polyhydramnios + double bubble on US; tx: surgical duodenoduodenostomy after cardiac evaluation',
    'apple core sign': "Apple Core Sign / Shouldering — concentric irregular narrowing of colon with overhanging edges on barium enema; classic for annular colorectal carcinoma; resembles core of an apple; most common in left colon; differential: Crohn's stricture (longer segment, smoother), diverticular stricture; requires colonoscopy + biopsy",
    'bird beak sign': 'Bird-Beak Sign — tapered narrowing of esophagus at GEJ on barium swallow; classic for achalasia (failure of LES relaxation + aperistalsis); also called rat-tail appearance; in sigmoid volvulus: funnel-shaped narrowing at obstruction site on barium enema (different bird beak); dx achalasia: manometry (gold standard)',
    'coffee bean sign': 'Coffee Bean Sign — massively dilated sigmoid colon on abdominal XR; closed-loop sigmoid volvulus; loop of colon folds on itself → oval/coffee bean shape in RUQ pointing toward RLQ; disproportionate sigmoid dilation; tx: sigmoidoscopic decompression (if no peritonitis); elective sigmoid resection after stabilization',
    'rigler sign': "Rigler's Sign (Double Wall Sign) — visualization of BOTH inner and outer walls of bowel on XR; indicates free intraperitoneal air (pneumoperitoneum); gas outlines OUTSIDE bowel wall; upright CXR (subdiaphragmatic free air) more sensitive; causes: perforated peptic ulcer (MCC), ruptured diverticulitis, perforated appendix, iatrogenic",
    'string sign': "String Sign — long, thin stream of contrast through severely narrowed bowel lumen on barium study; Crohn's disease: string sign of the terminal ileum (severe stricture from transmural inflammation/fibrosis); also: hypertrophic pyloric stenosis (string sign + shoulder sign + double track sign on upper GI); indicates significant luminal narrowing",
    'target sign': "Target Sign (Bull's Eye) — concentric ring appearance on ultrasound or CT; bowel wall = outer ring, intussuscepted bowel = inner ring, trapped mesentery = middle layer; intussusception (children — lead point often Meckel's diverticulum; adults — usually neoplasm); also: ischemic bowel (CT: target sign from submucosal edema)",
    'codman triangle': 'Codman Triangle — periosteal reaction lifted away from cortex by aggressive tumor forming a triangular shape at tumor margins; represents new periosteal bone formation at periphery of lesion; classic for osteosarcoma (also Ewing sarcoma); indicates aggressive bone lesion; not specific to malignancy (can be seen with osteomyelitis)',
    'sunburst pattern': 'Sunburst Pattern — spiculated periosteal reaction radiating from bone surface like sun rays; classic for osteosarcoma (aggressive periosteal new bone formation); combined with Codman triangle; most common at distal femur/proximal tibia metaphysis; peak age 10-20 years; ↑ALP; tx: neoadjuvant chemotherapy + limb-salvage surgery',
    'onion skin': 'Onion Skin (Lamellated) Periosteal Reaction — multiple parallel layers of periosteal new bone resembling onion layers; classic for Ewing sarcoma (aggressive periosteal reaction from rapid tumor growth); also: osteomyelitis, stress fracture, lymphoma; Ewing: diaphysis of long bones, pelvis; t(11;22) translocation; peak age 5-25 years; tx: chemo + radiation ± surgery',
    'erlenmeyer flask deformity': 'Erlenmeyer Flask Deformity — failure of normal bone remodeling with widening/flaring of distal femur metaphysis resembling Erlenmeyer flask; Gaucher disease (glucocerebrosidase deficiency → glucocerebroside accumulation in macrophages); also: Niemann-Pick, osteopetrosis, thalassemia, lead poisoning; Gaucher cells in marrow crowd out hematopoietic cells',
    'hair on end': 'Hair-on-End Skull — radial striations perpendicular to inner table of skull on lateral skull XR; medullary expansion by extramedullary hematopoiesis; classic for thalassemia major (and sickle cell disease, less severe); causes: severe hemolytic anemias with extramedullary hematopoiesis; also: hereditary spherocytosis, iron deficiency anemia (rare)',
    'rugger jersey spine': "Rugger Jersey Spine — alternating bands of sclerosis and lucency in vertebral bodies on spine XR; resembles striped rugby jersey; renal osteodystrophy (secondary hyperparathyroidism in CKD); dense endplates = reactive sclerosis; lucent middle = normal/osteopenic bone; also: osteopetrosis",
    'salt and pepper skull': 'Salt-and-Pepper Skull — granular mottled appearance of skull on XR; hyperparathyroidism (primary or secondary/tertiary); subperiosteal bone resorption → granular demineralization; ↑bone turnover; also: brown tumors (lucent expansile lesions), subperiosteal resorption radial side of middle phalanges; ↑PTH, ↓Ca (secondary) or ↑Ca (primary)',
    'thumb sign': 'Thumb Sign — thumbprint-like epiglottis on lateral soft tissue neck XR; epiglottitis (supraglottitis) — Haemophilus influenzae type b (pre-vaccine); now: Streptococcus, Candida; presents: high fever, drooling, dysphagia, stridor, tripod position; EMERGENCY; secure airway first; dx: lateral neck XR; do NOT examine throat in ED without airway backup',
    'steeple sign': 'Steeple Sign — subglottic narrowing tapering to a point on AP neck XR; croup (laryngotracheobronchitis) — parainfluenza virus type 1 (MCC); 6 months-3 years; barking cough, inspiratory stridor, low-grade fever; mild: racemic epinephrine + dexamethasone; lateral XR: normal epiglottis (distinguishes from epiglottitis)',

    'consolidation': "Consolidation — CT/CXR finding: area of ↑lung density obscuring underlying vessels with air bronchograms; alveoli filled with fluid (pus, blood, edema, cells); causes: pneumonia (lobar — air bronchograms, bacterial), pulmonary edema (bilateral, perihilar, Kerley B lines), ARDS, hemorrhage (trauma, vasculitis), alveolar cell carcinoma/adenocarcinoma, eosinophilic pneumonia; lobar consolidation with air bronchogram and fever = bacterial pneumonia until proven otherwise; bilateral perihilar 'bat-wing' = pulmonary edema",
    'honeycombing': "Honeycombing — HRCT: clustered cystic airspaces 3-10mm (occasionally up to 25mm) with thick, well-defined walls; subpleural distribution; key sign of end-stage fibrotic lung disease; causes: IPF (usual interstitial pneumonia pattern — UIP — subpleural, basal honeycombing + traction bronchiectasis ± ground glass), connective tissue disease (RA, SSc), asbestosis, hypersensitivity pneumonitis (chronic); IPF: honeycombing ± traction bronchiectasis without alternative diagnosis = UIP pattern → confident IPF diagnosis without biopsy",
    'miliary pattern': "Miliary Pattern — CXR/CT: innumerable tiny (1-3mm) nodules distributed randomly throughout both lungs, like millet seeds; causes: miliary TB (hematogenous dissemination — equal distribution; fever, night sweats, weight loss; diagnosis: sputum AFB, BAL, bone marrow biopsy — blood cultures low yield), miliary fungal infection (histoplasma, coccidioides), sarcoidosis (perilymphatic, not truly miliary), metastatic malignancy (thyroid, melanoma, renal cell — nodules may be larger), pneumoconiosis (silicosis — upper-lobe predominant)",
    'kerley a lines': "Kerley A Lines — long, non-branching linear opacities in upper/central lung zones extending to hilum (5-6cm); represent fluid/thickening in deep interstitial lymphatics; associated with pulmonary venous hypertension (pulmonary edema, mitral stenosis); less common than Kerley B lines; compare: Kerley B lines (short, horizontal at lung bases, peripheral, perpendicular to pleura — interlobular septa); Kerley C: reticular pattern throughout bases",
    'boot shaped heart': "Boot-Shaped Heart (Coeur en Sabot) — CXR: cardiac silhouette resembling a boot; upturned cardiac apex + concave main pulmonary artery segment (small pulmonary arteries due to ↓flow) + right ventricular hypertrophy; classic for Tetralogy of Fallot (right arch in 25%); TOF: VSD + overriding aorta + RVOT obstruction + RVH; cyanosis from R-to-L shunt through VSD; hypercyanotic ('Tet') spells: squat to ↑SVR → ↓R-to-L shunt; tx: BT shunt (palliation) → complete repair",
    'egg on string sign': "Egg on a String Sign — CXR: enlarged globular cardiac silhouette with narrow mediastinum ('string' = narrow pedicle); classic for Transposition of the Great Arteries (TGA); narrow mediastinum: great vessels superimposed (aorta anterior + to right of pulmonary artery, parallel rather than crossed) → narrow pedicle; egg-shaped cardiac silhouette from biventricular enlargement; TGA: most common cyanotic CHD presenting in newborns; requires prostaglandin E1 (keep PDA open) → balloon atrial septostomy → arterial switch operation",
    'snowman sign': "Snowman Sign (Figure of 8) — CXR: enlarged cardiac silhouette with figure-of-8 or snowman appearance; classic for Total Anomalous Pulmonary Venous Return (TAPVR) supracardiac type; upper 'snowball' = dilated SVC + innominate vein + left vertical vein; lower 'snowball' = heart; all 4 pulmonary veins drain to SVC rather than LA; cyanosis + pulmonary edema; requires surgery; obstructed TAPVR (infracardiac — drains to portal/hepatic vein): emergency, no snowman sign",
    'pleural effusion signs': "Pleural Effusion Radiographic Signs — CXR upright: blunting of costophrenic angle (>200 mL); meniscus sign (concave upper surface); >500mL: obscures hemidiaphragm; massive: mediastinal shift away; CXR supine (ICU): haziness of one hemithorax (layering); CT: crescent-shaped fluid along posterior chest wall; Subpulmonic effusion: apparent hemidiaphragm elevation + lateral peak shift; D-sign (flattening of left heart border): tension PTX (not effusion); differential by Light's criteria: exudate vs transudate",
    'tension pneumothorax': "Tension Pneumothorax — air accumulates under pressure in pleural space → mediastinal shift AWAY from affected side (compresses contralateral lung + great veins → ↓venous return → ↓CO → shock); causes: penetrating trauma, mechanical ventilation (barotrauma), rib fractures, ruptured bleb; CXR: absent lung markings, tracheal deviation away, ipsilateral hemidiaphragm flattening/depression; CLINICAL DIAGNOSIS — do NOT wait for CXR if unstable; tx: immediate needle decompression (2nd ICS, MCL or 4th-5th ICS, MAL) → chest tube; JVD + hypotension + absent breath sounds = Beck's triad equivalent for tension PTX",
    'air fluid level': "Air-Fluid Level — interface between gas and liquid on radiograph (upright or decubitus); requires air-fluid interface; gastric/bowel obstruction: step-ladder air-fluid levels (SBO); abscesses (lung abscess: thick-walled cavity with air-fluid level); empyema with bronchopleural fistula; hiatal hernia (gastric air bubble in posterior mediastinum); Ogilvie syndrome (colonic pseudo-obstruction); absence of haustral folds in large bowel = colonic; presence of valvulae conniventes = small bowel",
    'silhouette sign': 'Silhouette Sign — loss of a normal border between soft tissue and air when adjacent lung fills with fluid or tissue of the same density; localizes disease on a frontal CXR: right heart border lost → right middle lobe; left heart border → lingula; hemidiaphragm → lower lobe; aortic knob → left upper lobe; an opacity over the heart with a preserved border lies posteriorly (lower lobe)',
    'deep sulcus sign': 'Deep Sulcus Sign — abnormally deep, lucent costophrenic angle on a SUPINE chest radiograph; pleural air collects anteriorly and inferiorly when the patient lies flat; indicates pneumothorax in supine trauma/ICU patients, where the usual apical pleural line is absent; confirm with ultrasound (absent lung sliding) or CT',
    'golden s sign': 'Golden S Sign — reverse-S shaped fissure on CXR in right upper lobe collapse: the minor fissure is pulled up laterally (concave) but bulges medially (convex) around a central hilar mass; strongly suggests an obstructing central tumor (bronchogenic carcinoma) in an adult',
    'widened mediastinum': "Widened Mediastinum — mediastinal width >8 cm on a PA chest radiograph (AP/supine films exaggerate it); with trauma or tearing chest/back pain think aortic dissection or traumatic aortic injury (also loss of the aortic knob, deviated trachea or NG tube, left apical cap) → CT angiography; other causes: anterior mediastinal masses (the 4 Ts — thymoma, teratoma, thyroid, 'terrible' lymphoma), inhalational anthrax (hemorrhagic mediastinitis)",
    'water bottle heart': 'Water-Bottle Heart — symmetrically enlarged, globular cardiac silhouette with a narrow base (flask shape) on CXR; suggests a large pericardial effusion — rapid enlargement with clear lungs favors effusion over cardiomyopathy; confirm with echocardiography (tamponade: RA/RV diastolic collapse)',
    'popcorn calcification': 'Popcorn Calcification — clustered, coarse, ring-and-arc calcification in a well-defined lung nodule; characteristic of pulmonary hamartoma (most common benign lung tumor; fat on CT is diagnostic); in the breast, coarse popcorn calcification = involuting fibroadenoma; benign lung patterns: central, laminated, diffuse, popcorn — eccentric or stippled calcification is suspicious',
    'eggshell calcification': "Eggshell Calcification — thin peripheral rim calcification of hilar/mediastinal lymph nodes; classic for silicosis, also coal workers' pneumoconiosis and sarcoidosis; rarely treated lymphoma or histoplasmosis",
    'football sign': "Football Sign — large oval lucency outlining the abdomen on a supine radiograph, with the falciform ligament as the 'laces'; massive pneumoperitoneum — classic in neonates with perforated necrotizing enterocolitis, also adult viscus perforation; needs emergent surgical evaluation",
    'lead pipe colon': 'Lead-Pipe Colon — featureless, narrowed, shortened colon with loss of haustral markings on barium enema or CT; longstanding ulcerative colitis; contrast Crohn disease: skip lesions, string sign, cobblestoning, fistulas',
    'thumbprinting': "Thumbprinting — thickened, edematous colonic folds indenting the lumen like thumbprints on plain film, barium study or CT; bowel wall edema/hemorrhage: ischemic colitis (classic — splenic flexure watershed), C. difficile colitis, infectious colitis, IBD; different from the 'thumb sign' of epiglottitis on a lateral neck film",
    'whirlpool sign': 'Whirlpool Sign — swirling of the mesentery and vessels around a central axis on CT or Doppler ultrasound; indicates volvulus/torsion: midgut volvulus with malrotation (neonate with bilious vomiting — surgical emergency), small bowel or cecal volvulus; also ovarian and testicular torsion on ultrasound',
    'hyperdense mca sign': "Hyperdense MCA Sign — bright (hyperattenuating) middle cerebral artery on non-contrast head CT from acute intraluminal thrombus; an early sign of large-vessel occlusion stroke before parenchymal changes appear; prompts CT angiography and assessment for thrombolysis/mechanical thrombectomy; the 'dot sign' is the same finding in an MCA branch in the Sylvian fissure",
    'ring enhancing lesion': "Ring-Enhancing Brain Lesion — rim of contrast enhancement around a low-density core on CT/MRI; differential 'MAGIC DR': Metastasis, Abscess, Glioblastoma, Infarct (subacute), Contusion, Demyelination (incomplete 'open' ring — MS), Radiation necrosis; in AIDS: toxoplasmosis (multiple, basal ganglia) vs primary CNS lymphoma (solitary, periventricular); abscess shows restricted diffusion on DWI",
    'bamboo spine': 'Bamboo Spine — smooth, continuous vertebral outline from fused syndesmophytes and ossified ligaments on spine radiograph; late ankylosing spondylitis (HLA-B27); earlier signs: bilateral sacroiliitis, squaring of vertebral bodies (shiny corners), dagger sign; the fused spine fractures after minor trauma',
    'pencil-in-cup deformity': 'Pencil-in-Cup Deformity — erosion of the distal end of one phalanx (pencil) with cupping of the adjacent base (cup), usually at DIP joints; classic for psoriatic arthritis (arthritis mutilans); contrast RA (marginal erosions at MCP/PIP, periarticular osteopenia, symmetric) and gout (punched-out erosions with overhanging edges)',
    'sail sign': 'Sail Sign — triangular opacity; (1) infants: normal thymus projecting from the mediastinum on CXR; (2) elbow: a lifted anterior fat pad (and any visible posterior fat pad) on a lateral radiograph = joint effusion → occult fracture (supracondylar in children, radial head in adults); (3) left lower lobe collapse behind the heart',
    'cannonball metastases': 'Cannonball Metastases — multiple large, well-defined round lung nodules of varying size, mostly in the lower zones; hematogenous spread from renal cell carcinoma (classic), choriocarcinoma, sarcomas, testicular germ cell tumors, colorectal cancer',
    'cardiothoracic ratio': 'Cardiothoracic Ratio — maximal cardiac width ÷ maximal internal thoracic width on a PA chest radiograph; >0.5 suggests cardiomegaly or pericardial effusion; unreliable on AP/supine films (magnify the heart) and with poor inspiration',
    'pneumoperitoneum': 'Pneumoperitoneum — free intraperitoneal air; best seen as a lucent crescent under the hemidiaphragm on an erect CXR (left lateral decubitus film if the patient cannot stand); supine signs: Rigler (double wall), football sign, falciform ligament sign; causes: perforated peptic ulcer or diverticulum (surgical emergency), recent laparotomy/laparoscopy (expected), peritoneal dialysis; CT is most sensitive',
    'snowstorm pattern': "Snowstorm Pattern — heterogeneous echogenic intrauterine mass with many small cystic spaces ('cluster of grapes') and no fetus on ultrasound; COMPLETE HYDATIDIFORM MOLE; often with bilateral theca lutein cysts and very high β-hCG; partial mole shows a fetus with a thickened, cystic placenta",
    'double decidual sign': 'Double Decidual Sign — two concentric echogenic rings (decidua capsularis and parietalis) around an early gestational sac on transvaginal ultrasound; supports an INTRAUTERINE pregnancy before the yolk sac is seen (yolk sac at ~5.5 weeks is the definitive first sign); a single-ring fluid collection may be a pseudosac of ectopic pregnancy',
    'ring of fire sign': 'Ring of Fire Sign — circumferential peripheral hypervascularity on color Doppler around an adnexal mass; seen with ECTOPIC pregnancy (tubal ring) and with a CORPUS LUTEUM cyst (on the ovary itself) — location relative to the ovary distinguishes them',
    'lemon sign': 'Lemon Sign — scalloping (inward bowing) of the frontal bones on the axial fetal head ultrasound in the 2nd trimester; associated with open NEURAL TUBE DEFECTS (myelomeningocele, Chiari II); usually disappears after 24 weeks',
    'banana sign': 'Banana Sign — cerebellum wrapped around the brainstem (obliterated cisterna magna) on fetal ultrasound; Chiari II malformation from open spina bifida (myelomeningocele) — together with the lemon sign and elevated maternal serum AFP',
    'string of pearls sign': 'String of Pearls Sign — ≥20 small peripheral follicles (2–9 mm) arranged around an enlarged, echogenic ovarian stroma on transvaginal ultrasound; POLYCYSTIC OVARIAN MORPHOLOGY (one Rotterdam criterion for PCOS); also called the necklace sign',
    'twin peak sign': 'Twin Peak (Lambda) Sign — triangular chorionic tissue extending between the two layers of the intertwin membrane in the 1st trimester; indicates DICHORIONIC twins; the T sign (thin membrane meeting the placenta at a right angle) indicates MONOCHORIONIC-diamniotic twins (risk of twin-twin transfusion)',
    'whirlpool sign ovary': 'Whirlpool Sign (ovary) — twisted vascular pedicle seen as a swirling target on color Doppler next to an enlarged edematous ovary; OVARIAN TORSION (normal Doppler flow does NOT exclude torsion)',
}
